// Compare current MX/SPF/DMARC/DKIM presence against last run (workflow static data),
// so we alert on NEW breakage, not just re-alert on a known problem every week.
// This is genuinely stateful logic - no core node remembers prior executions, so Code earns its place here.
const staticData = $getWorkflowStaticData('global');
if (!staticData.emailAuthState) staticData.emailAuthState = {};

const domain = $('Split Domain Records').item.json.domain;

const raw = $json;
const body = raw.response || raw;
const records = Array.isArray(body) ? body : (Array.isArray(body.data) ? body.data : []);

const isLive = (rec) => (rec.records || []).some(r => !r.is_disabled);

const mx = records.filter(r => r.type === 'MX' && isLive(r));
const spf = records.filter(r => r.type === 'TXT' && (r.name === '@' || r.name === domain)
  && (r.records || []).some(x => !x.is_disabled && (x.content || '').toLowerCase().includes('v=spf1')));
const dmarc = records.filter(r => r.type === 'TXT' && (r.name || '').toLowerCase() === '_dmarc'
  && (r.records || []).some(x => !x.is_disabled && (x.content || '').toLowerCase().includes('v=dmarc1')));
const dkim = records.filter(r => r.type === 'TXT' && (r.name || '').toLowerCase().includes('_domainkey') && isLive(r));

const current = { MX: mx.length > 0, SPF: spf.length > 0, DMARC: dmarc.length > 0, DKIM: dkim.length > 0 };
const previous = staticData.emailAuthState[domain] || {};
const problems = [];

for (const key of Object.keys(current)) {
  if (!current[key]) {
    const wasOkBefore = previous[key] !== false;
    problems.push({ record: key, isNew: wasOkBefore });
  }
}

staticData.emailAuthState[domain] = current;

return [{ json: { domain, hasIssues: problems.length > 0, problems } }];

// Templating a looped HTML table - this is what Code is genuinely good for; a Set expression
// can't cleanly loop and build markup like this.
const domain = $json.domain;
const problems = $json.problems;

const descriptions = {
  MX: 'No active MX record - this domain cannot receive mail at all.',
  SPF: 'No valid SPF TXT record at the root - receiving servers may reject or spam-flag your mail.',
  DMARC: 'No valid DMARC TXT record at _dmarc - domain is exposed to spoofing and won\'t get delivery reports.',
  DKIM: 'No DKIM (_domainkey) TXT record found - outgoing mail may fail signature checks.'
};

const rows = problems.map(p => `
<tr>
  <td>${p.record}</td>
  <td>${p.isNew ? '\uD83C\uDD95 New' : 'Ongoing'}</td>
  <td>${descriptions[p.record]}</td>
</tr>`).join('');

const html = `
<h2>Email authentication issue detected: ${domain}</h2>
<p>The following DNS records affecting mail deliverability are missing or invalid:</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">
<tr><th>Record</th><th>Status</th><th>Why it matters</th></tr>
${rows}
</table>
<p>Add or fix these records in your DNS zone - this check will confirm the fix automatically next run.</p>
`;

return [{ json: { subject: `\u26A0\uFE0F Email authentication issue on ${domain}`, html } }];
